new Cmd{Cat="鼠标相关", Name="鼠标左键按下", Code="鼠标左键按下()\r\n", Usage="<p>鼠标左键按下()</p>\r\n<p>鼠标左键按下(x坐标,y坐标)</p>\r\n<p>鼠标左键按下(x坐标,y坐标,随机左偏移,随机上偏移,随机右偏移,随机下偏移)</p>\r\n<p>鼠标左键按下(x坐标,y坐标,随机左偏移,随机上偏移,随机右偏移,随机下偏移, 执行次数, 每次延迟时间)</p>\r\n<p>其中时间是毫秒</p>\r\n<p>x与y坐标同时为-1时表示不移动</p>"},
new Cmd{Cat="鼠标相关", Name="鼠标相对移动", Code="鼠标相对移动(100, 100)\r\n", Usage="<p>[不推荐使用]以当前坐标为起点，向指定方向移动</p>\r\n<p>鼠标相对移动(x坐标,y坐标)</p>\r\n<p>鼠标相对移动(x坐标,y坐标,随机左偏移,随机上偏移,随机右偏移,随机下偏移)</p>\r\n<p>鼠标相对移动(x坐标,y坐标,随机左偏移,随机上偏移,随机右偏移,随机下偏移, 执行次数, 每次延迟时间)</p>\r\n<p>其中时间是毫秒</p>\r\n<p>x与y坐标同时为-1时表示不移动</p>"},
new Cmd{Cat="鼠标相关", Name="鼠标移动", Code="鼠标移动(100, 100)\r\n", Usage="<p>鼠标移动(x坐标,y坐标)</p>\r\n<p>鼠标移动(x坐标,y坐标,随机左偏移,随机上偏移,随机右偏移,随机下偏移)</p>\r\n<p>鼠标移动(x坐标,y坐标,随机左偏移,随机上偏移,随机右偏移,随机下偏移, 执行次数, 每次延迟时间)</p>\r\n<p>其中时间是毫秒</p>"},
new Cmd{Cat="算法与数学", Name="余弦值", Code="a = 余弦值(90)", Usage="<p>获取指定角度的余弦值</p>\r\n<p>用法:</p>\r\n<p>a = 余弦值(90)</p>\r\n<p>a将变为一个小数</p>"},
new Cmd{Cat="算法与数学", Name="反余弦值", Code="a = 反余弦值(1.5)", Usage="<p>获取反余弦值</p>\r\n<p>用法:</p>\r\n<p>a = 反余弦值(1.5)</p>\r\n<p>a将变为一个小数</p>"},
new Cmd{Cat="算法与数学", Name="反正切值", Code="a = 反正切值(1.5)", Usage="<p>获取反正切值</p>\r\n<p>用法:</p>\r\n<p>a = 反正切值(1.5)</p>\r\n<p>a将变为一个小数</p>"},
new Cmd{Cat="算法与数学", Name="反正弦值", Code="a = 反正弦值(1.5)", Usage="<p>获取反正弦值</p>\r\n<p>用法:</p>\r\n<p>a = 反正弦值(1.5)</p>\r\n<p>a将变为一个小数</p>"},
new Cmd{Cat="算法与数学", Name="幂函数", Code="#计算5的6次方\r\na = 幂函数(5, 6)", Usage="<p>获取x的y次方的值</p>\r\n<p>用法:</p>\r\n<p>a = 幂函数(x, y)</p>\r\n<p>a将变为小数</p>"},
new Cmd{Cat="算法与数学", Name="最大值", Code="#返回下方多个数字中最大的一个\r\na = 最大值(1, 100, 2, 5, 33, 5)", Usage="<p>返回指定的多个数字中最大的一个</p>\r\n<p>调用方法: </p>\r\n<p>a = 最大值(数字1, 数字2, 数字3, 数字4, ...)</p>\r\n"},
new Cmd{Cat="算法与数学", Name="最小值", Code="#返回下方多个数字中最小的一个\r\na = 最小值(1, 100, 2, 5, 33, 5)", Usage="<p>返回指定的多个数字中最小的一个</p>\r\n<p>调用方法: </p>\r\n<p>a = 最小值(数字1, 数字2, 数字3, 数字4, ...)</p>\r\n"},
new Cmd{Cat="算法与数学", Name="正切值", Code="a = 正切值(90)", Usage="<p>获取指定角度的正切值</p>\r\n<p>用法:</p>\r\n<p>a = 正切值(90)</p>\r\n<p>a将变为一个小数</p>"},
new Cmd{Cat="算法与数学", Name="正弦值", Code="a = 正弦值(90)", Usage="<p>获取指定角度的正弦值</p>\r\n<p>用法:</p>\r\n<p>a = 正弦值(90)</p>\r\n<p>a将变为一个小数</p>"},
new Cmd{Cat="算法与数学", Name="求平方根", Code="#求指定数字的平方根\r\na = 求平方根(25)", Usage="<p>求指定数的平方根</p>\r\n<p>用法:</p>\r\n<p>a = 求平方根(25)</p>\r\n<p>a将是一个小数类型</p>"},
new Cmd{Cat="算法与数学", Name="绝对值", Code="a = 绝对值(-90)", Usage="<p>获取绝对值</p>\r\n<p>用法:</p>\r\n<p>a = 绝对值(-90)</p>\r\n<p>a将变为一个正整数</p>"},
new Cmd{Cat="图色查找", Name="多点查找颜色", Code="#在指定范围内查找rgb为ff0000且偏移0,4颜色为ffff00且偏移4,4颜色为ffffff，相似度为1的颜色\r\n多点查找颜色(0, 0, 686, 568, \"ff0000\", \"0|4|ffff00,4|4|ffffff\", 1, 0, x, y)\r\n如果(x >= 0 && y >= 0)\r\n开始\r\n                #这里表示找到了颜色\r\n                鼠标移动(x, y)\r\n结束", Usage="<p>通过rgb来多点查找颜色</p>\r\n<p>成功a为1，失败a为0</p>\r\n<p>a = 查找颜色(左, 上, 右, 下, \"颜色\", \"偏移颜色\", 相似度(1.0 - 0.5), 0, x, y)</p>\r\n<br/>\r\n<p>其中颜色格式为rrggbb，也就是ff00ff这样的<p>\r\n<p>其中偏移颜色格式为x|y|rrggbb，也就是0|1|ff0000这样的<p>\r\n"},
new Cmd{Cat="图色查找", Name="屏幕截图", Code="#屏幕截图,并保存到路径C:\\1.bmp\r\n屏幕截图(0, 0, 1920, 1080, \"C:\\1.bmp\")", Usage="<p>获取屏幕中指定范围的图片,并保存到指定路径</p>\r\n<p>成功返回1，失败返回0</p>\r\n<p>屏幕截图(左, 上, 右, 下, \"保存路径\")</p>\r\n<br/>\r\n<p>注:保存格式为bmp</p>\r\n"},
new Cmd{Cat="图色查找", Name="查找图片", Code="#在指定范围内查找名称为1.bmp, 相似度为0.95的图片\r\na = 查找图片(0, 0, 500, 500, \"1.bmp\", \"000000\", 0.95, 0, x, y)\r\n如果(a == 1)\r\n开始\r\n	#找到了，弹出一个框\r\n	消息框(\"提示\", \"找到了图片, x:\", x, \", y:\", y)\r\n结束", Usage="<p>通过rgb来查找颜色</p>\r\n<p>成功a为1，失败a为0</p>\r\n<p>a = 查找图片(左, 上, 右, 下, \"图片名\", \"偏色\", 相似度(1.0 - 0.5), 0, x, y)</p>\r\n<br/>\r\n<p>极速模式支持bmp jpg png图片格式，但是相似度要调低一点</p>\r\n<p>高速模式、兼容模式仅支持bmp图片格式</p>"},
new Cmd{Cat="图色查找", Name="查找图片返回多张", Code="#在指定范围内查找名称为1.bmp, 相似度为0.95的图片, 并将找到的数量保存到n里, 并点击所有找到的图片\r\nn = 查找图片返回多张(0, 0, 500, 500, \"1.bmp\", \"000000\", 0.95, 0, x, y, name)\r\n如果(n > 0)\r\n开始\r\n	i = 0\r\n	循环(i < n)\r\n	开始\r\n		鼠标移动(x[i], y[i])\r\n		鼠标左键单击()\r\n		延迟(500)\r\n		i = i + 1\r\n	结束\r\n结束", Usage="<p>查找指定图片, 并返回找到的多张图片坐标</p>\r\n<p>成功n为数量，失败a为0</p>\r\n<p>a = 查找图片返回多张(左, 上, 右, 下, \"图片名\", \"偏色\", 相似度(1.0 - 0.5), 0, x, y, name)</p>\r\n<br/>\r\n<p>获取到的图片信息为数组格式: x, y, name</p>\r\n<p>提取方式第一张找到的图片方式为 x[0] y[0] name[0]</p>\r\n<p>极速模式支持bmp jpg png图片格式，但是相似度要调低一点</p>\r\n<p>高速模式、兼容模式仅支持bmp图片格式</p>"},
new Cmd{Cat="图色查找", Name="查找颜色", Code="#在指定范围内查找rgb为112233, 相似度为0.95的颜色\r\na = 查找颜色(0, 0, 500, 500, \"112233\", 0.95, 0, x, y)\r\n如果(a == 1)\r\n开始\r\n	#找到了，弹出一个框\r\n	消息框(\"提示\", \"找到了颜色, x:\", x, \", y:\", y)\r\n结束", Usage="<p>通过rgb来查找颜色</p>\r\n<p>成功a为1，失败a为0</p>\r\n<p>a = 查找颜色(左, 上, 右, 下, \"颜色\", 相似度(1.0 - 0.5), 0, x, y)</p>\r\n<br/>\r\n<p>其中颜色格式为rrggbb，也就是112233这样的<p>\r\n"},
new Cmd{Cat="图色查找", Name="获取图片", Code="#获取绑定窗口的图片,保存到路径C:\\1.bmp\r\n获取图片(0, 0, 500, 500, \"C:\\1.bmp\")", Usage="<p>获取已经绑定窗口的图片,并保存到指定路径</p>\r\n<p>成功a为1，失败a为0</p>\r\n<p>a = 获取图片(左, 上, 右, 下, \"保存路径\")</p>\r\n<br/>\r\n<p>注:保存格式为bmp</p>\r\n"},
new Cmd{Cat="图色查找", Name="获取颜色", Code="#获取5x5坐标上的颜色,并保存到变量a里,格式为rrggbb\r\na = 获取颜色(5,5)", Usage="<p>通过指定坐标来获取颜色</p>\r\n<p>成功a为坐标值(字符串)，失败a为空字符串</p>\r\n<p>a = 获取颜色(x坐标, y坐标)</p>\r\n<br/>\r\n<p>其中颜色格式为rrggbb，也就是112233这样的<p>\r\n"},
new Cmd{Cat="图色查找", Name="获取颜色数量", Code="#获取0,0,400,300范围中指定颜色的数量,并保存到变量a里\r\na = 获取颜色数量(0, 0, 400, 300, \"101010\")", Usage="<p>获取指定范围中指定颜色的数量</p>\r\n<p>返回颜色的数量</p>\r\n<p>a = 获取颜色数量(范围左, 范围上, 范围右, 范围下, \"颜色数据\")</p>\r\n<br/>\r\n<p>其中颜色数据格式为rrggbb，也就是112233这样的<p>\r\n"},
new Cmd{Cat="文本识别查找", Name="文本查找", Code="#在指定范围内查找, 并存入指定变量中\r\nn = 文本查找(0, 0, 200, 200, 0.6, 0.3, \"文本\", 0, 0, left, top, right, bottom, text, \"\")\r\n如果(n > 0)\r\n开始\r\n	#找到了，弹出一个框, 提示信息\r\n	消息框(\"提示\", \"找到了文本, 第一条 text: \", text[0], \", left:\", left[0], \", top:\", top[0], \", right:\", right[0], \", bottom:\", bottom[0])\r\n结束", Usage="<p>指定一个范围, 查找指定的文本, 并返回找到的文本的坐标以及文本信息</p>\r\n<p>成功n大于0，失败n为0</p>\r\n<p>n = 文本查找(左, 上, 右, 下, 文本置信度, 文本框置信度, \"要查找的文本\", 是否包含匹配, 是否返回多条信息, 左变量, 上变量, 右变量, 下变量, 文本变量, \"输出图片路径(不填则不输出)\")</p>\r\n<br/>\r\n<p>通过n是否大于0来判断是否查找到<p>\r\n<p>识别的结果将以\"数组\"格式存放到你指定的变量中</p>\r\n<p>例如: 如果你的左上右下文本变量分别填写为: left top right bottom text</p>\r\n<p>假设n为2, 那么提取识别到的第一条信息则为left[0] top[0] right[0] bottom[0] text[0]</p>\r\n<p>第二条就把0改为1就行了,依次往后</p>\r\n<p></p>\r\n<p>注: 如果你要同时查找几个文本, 那么你可以用以下格式输入 \"文本1|文本2|文本3\", 用|隔开就行了</p>\r\n"},
new Cmd{Cat="文本识别查找", Name="文本识别", Code="#在指定范围内识别文本, 并存入指定变量中\r\nn = 文本识别(0, 0, 200, 200, 0.6, 0.3, left, top, right, bottom, text, \"\")\r\n如果(n > 0)\r\n开始\r\n	#找到了，弹出一个框, 提示信息\r\n	消息框(\"提示\", \"找到了文本, 第一条 text: \", text[0], \", left:\", left[0], \", top:\", top[0], \", right:\", right[0], \", bottom:\", bottom[0])\r\n结束", Usage="<p>指定一个范围, 识别所有的文本, 并返回识别的文本，以及文本的左上右下四个信息</p>\r\n<p>成功n大于0，失败n为0</p>\r\n<p>n = 文本识别(左, 上, 右, 下, 文本置信度, 文本框置信度 左变量, 上变量, 右变量, 下变量, 文本变量, \"输出图片路径(不填则不输出)\")</p>\r\n<br/>\r\n<p>通过n是否大于0来判断是否识别到有效内容<p>\r\n<p>识别的结果将以\"数组\"格式存放到你指定的变量中</p>\r\n<p>例如: 如果你的左上右下文本变量分别填写为: left top right bottom text</p>\r\n<p>假设n为2, 那么提取识别到的第一条信息则为left[0] top[0] right[0] bottom[0] text[0]</p>\r\n<p>第二条就把0改为1就行了,依次往后</p>\r\n"},
new Cmd{Cat="文件相关", Name="写入文本文件", Code="#写入文本文件内容，失败返回1，成功返回0\r\na = 写入文本文件(\"C:\\1.txt\", \"123\")", Usage="<p>写入文本文件内容</p>\r\n<p>成功a为1，失败a为0</p>\r\n<p>变量 a = 写入文本文件(\"文件路径\", \"内容\")</p>\r\n"},
new Cmd{Cat="文件相关", Name="执行任务文件", Code="#执行C盘下的1.txt任务文件\r\n执行任务文件 C:\\1.txt", Usage="<p>执行任务文件</p>\r\n<p>一个文件写代码有时候过于臃肿，可以将代码写在其它文件，并通过该功能进行调用</p>\r\n<p>使用说明</p>\r\n<p>执行任务文件 \"任务路径\"</p>\r\n<p></p>\r\n<p>下面举个例子:</p>\r\n<p>执行任务文件 \"C:\\1.txt\"</p>"},
new Cmd{Cat="文件相关", Name="获取文件大小", Code="#获取文件大小，失败返回-1，成功则>=0\r\na = 获取文件大小(\"C:\\\\1.txt\")", Usage="<p>通过文件路径，获取文件大小</p>\r\n<p>成功a为1，失败a为0</p>\r\n<p>        变量 a = 获取文件大小(\"文件路径\")</p>\r\n"},
new Cmd{Cat="文件相关", Name="读取文本文件", Code="#读取文本文件内容，失败返回1，成功返回0\r\na = 读取文本文件(\"C:\\1.txt\", text)", Usage="<p>读取文本文件内容</p>\r\n<p>成功a为1,并将读取到的内容存到变量中.失败a为0</p>\r\n<p>变量 a = 读取文本文件(\"文件路径\", 变量)</p>\r\n"},
new Cmd{Cat="文件相关", Name="追加文本文件", Code="#追加文本文件内容，失败返回1，成功返回0\r\na = 追加文本文件(\"C:\\1.txt\", \"123\")", Usage="<p>追加文本文件内容</p>\r\n<p>成功a为1，失败a为0</p>\r\n<p>变量 a = 追加文本文件(\"文件路径\", \"追加内容\")</p>\r\n"},
new Cmd{Cat="语法", Name="变量", Code="#定义三个变量，一个整形，一个字符串，一个小数\r\n变量 a = 5\r\n变量 b = \"字符串\"\r\n变量 c = 1.123", Usage="<p>定义变量可以较为随意, 目前只支持整数与字符串与小数，大致有以下几种方式</p>\r\n<p>第一种:</p>\r\n<p>        变量 a = 5</p>\r\n<p>第二种:</p>\r\n<p>        b = 5</p>\r\n<p>第三种(这是字符串):</p>\r\n<p>        c = \"我是字符串\"</p>\r\n<p>第四种(这是小数):</p>\r\n<p>        d = 1.123</p>"},
new Cmd{Cat="语法", Name="多线程", Code="#一个启动多个线程, 并等待执行的例子\r\n子任务 线程测试1()\r\n	消息框(\"我是线程1\")\r\n子任务完成\r\n\r\n子任务 线程测试2()\r\n	消息框(\"我是线程2\")\r\n子任务完成\r\n\r\nid1 = 启动线程(\"线程测试1\")\r\nid2 = 启动线程(\"线程测试2\")\r\n等待线程(id1)\r\n等待线程(id2)", Usage="<p>启动一个线程, 并发执行操作</p>\r\n<p>调用方式:</p>\r\n<p>tid = 启动线程(\"子任务名\")</p>\r\n<br/>\r\n<p>说明:</p>\r\n<p>线程中的子任务必须是没有参数的</p>\r\n<p>调用方式可以有以下几种:</p>\r\n<p>启动线程(\"子任务名\")</p>\r\n<p>tid = 启动线程(\"子任务名\")</p>\r\n<p>注意:这里的tid表示这个线程的编号(每个线程唯一)</p>\r\n<p>注意2: 启动线程执行后会立即往后面执行别的操作, 如果想等待线程执行结束, 那么需要用如下的方式:</p>\r\n<p>等待线程(tid)</p>\r\n<p>通过上面的方式等待这个线程执行结束，再继续往后执行</p>"},
new Cmd{Cat="语法", Name="如果", Code="#当a等于5时执行 鼠标左键单击\r\n#当a等于6时执行 鼠标左键双击\r\n#否则执行 鼠标右键双击\r\n如果(a==5)\r\n开始\r\n	鼠标左键单击()\r\n结束\r\n否则如果(a==6)\r\n开始\r\n	鼠标左键双击()\r\n结束\r\n否则\r\n开始\r\n	鼠标右键单击()\r\n结束", Usage="<p>如果(值)</p>\r\n<p>开始</p>\r\n<p>        某某代码</p>\r\n<p>结束</p>\r\n<p>否则如果(值)</p>\r\n<p>开始</p>\r\n<p>        某某代码</p>\r\n<p>结束</p>\r\n<p>否则</p>\r\n<p>开始</p>\r\n<p>        某某代码</p>\r\n<p>结束</p>\r\n<br/>\r\n<p>大概用法如上</p>\r\n<p>先写个\"如果\", 当括号里的\"值\"不等于0时，就会执行\"开始\"与\"结束\"里面的代码</p>\r\n<p>相信聪明的你，已经知道怎么使用了吧</p>"},
new Cmd{Cat="语法", Name="子任务(函数)", Code="#一个从1...n的累加例子\r\n子任务 累加(n)\r\n	i = 0\r\n	s = 0\r\n	循环(i < n)\r\n	开始\r\n		s = s + i\r\n		i = i + 1\r\n	结束\r\n\r\n	返回 s\r\n子任务完成\r\n\r\n#这里是调用子任务，并弹出提示框显示结果\r\na = 累加(100)\r\n消息框(a)", Usage="<p>子任务(函数)</p>\r\n<p>定义方式如下：</p>\r\n<p></p>\r\n<p>子任务 任务名(参数1, 参数2)</p>\r\n<p>......这里是代码</p>\r\n<p>子任务完成</p>\r\n<p></p>\r\n<p>调用方式:</p>\r\n<p>a = 任务名()</p>\r\n<br/>\r\n<p>说明:</p>\r\n<p>任务名可以是中文</p>\r\n<p>子任务中的所有变量，都是全局变量，除了参数传入了变量的参数</p>\r\n<p>......举个例子：子任务 sum(a, b)</p>\r\n<p>......然后调用：sum(dd, 2)</p>\r\n<p>这个时候如果在子任务中修改a的值，其实是修改dd的值</p>\r\n<p>这个时候如果在子任务中修改b的值，其实是修改全局变量b的值</p>\r\n<p>调用方式可以有以下几种:</p>\r\n<p>sum(100)</p>\r\n<p>a = sum(100)</p>\r\n<p>不可以用以下的调用方式(内置的函数可以这样):</p>\r\n<p>a = sum(100) + 1</p>"},
new Cmd{Cat="语法", Name="循环", Code="#当a小于5时执行 鼠标左键单击\r\n变量 a = 0\r\n循环(a<5)\r\n开始\r\n	鼠标左键单击()\r\n	a = a + 1\r\n	延迟(500)\r\n结束", Usage="<p>循环(值)</p>\r\n<p>开始</p>\r\n<p>        某某代码</p>\r\n<p>结束</p>\r\n<br/>\r\n<p>大概用法如上</p>\r\n<p>先写个\"循环\", 当括号里的\"值\"不等于0时，就会执行\"开始\"与\"结束\"里面的代码</p>"},
new Cmd{Cat="语法", Name="继续循环", Code="#执行到该行继续当前循环，等同于continue\r\n继续循环\r\n", Usage="<p>继续循环</p>"},
new Cmd{Cat="语法", Name="跳出循环", Code="#执行到该行跳出当前循环，等同于break\r\n跳出循环\r\n", Usage="<p>跳出循环</p>"},
new Cmd{Cat="字符串剪切板", Name="发送剪切板", Code="#对已绑定的窗口发送剪切板文字\r\n发送剪切板()", Usage="<p>对已绑定的窗口发送剪切板文字</p>\r\n<p>成功返回1，失败返回0</p>\r\n<p>发送剪切板()</p>\r\n"},
new Cmd{Cat="字符串剪切板", Name="发送字符串", Code="#对已绑定的窗口发送指定字符串\r\n发送字符串(\"123456\")", Usage="<p>对已绑定的窗口发送指定字符串</p>\r\n<p>成功返回1，失败返回0</p>\r\n<p>发送字符串(\"123456\")</p>\r\n"},
new Cmd{Cat="字符串剪切板", Name="发送字符串2", Code="#对已绑定的窗口发送指定字符串\r\n发送字符串2(\"123456\")", Usage="<p>对已绑定的窗口发送指定字符串</p>\r\n<p>成功返回1，失败返回0</p>\r\n<p>发送字符串2(\"123456\")</p>\r\n"},
new Cmd{Cat="字符串剪切板", Name="字符串长度", Code="#获取长度\r\nn = 字符串长度(\"abc阿萨德\")", Usage="<p>获取指定字符串的长度, 返回长度</p>\r\n<p>用法:</p>\r\n<p>s = 字符串长度(\"字符串\")</p>"},
new Cmd{Cat="字符串剪切板", Name="拆分字符串", Code="#以|为基准, 拆分字符串的内容, 并将结果保存到变量a中(数组)\r\nn = 拆分字符串(\"asd|dsa|123\", \"|\", a)\r\ni = 0\r\ns = \"\"\r\n循环(i < n)\r\n开始\r\n	s = s + a[i] + \"\\n\"\r\n	i = i + 1\r\n结束\r\n消息框(\"提示\", s)", Usage="<p>拆分字符串的内容, 并将结果保存到指定的数组变量中, 同时返回拆分后的数组元素个数</p>\r\n<p>用法:</p>\r\n<p>n = 拆分字符串(\"字符串\", \"根据什么拆\", 数组变量)</p>"},
new Cmd{Cat="字符串剪切板", Name="提取字符串", Code="#从字符串abc123中提取索引为1的字符, 并保存到a里\r\na = 提取字符串(\"abc123\", 1)\r\n#从字符串abc123中索引为1的位置开始提取3个连续的字符, 并保存到b里\r\nb = 提取字符串(\"abc123\", 1, 3)", Usage="<p>从字符串中提取指定的字符串</p>\r\n<p>用法:</p>\r\n<p>a = 提取字符串(\"要提取的字符串\", 从哪提取, 提取多少个(不填写就是1, 填写-1表示提取后面所有))</p>"},
new Cmd{Cat="字符串剪切板", Name="是否包含字符串", Code="#判断abc123中是否包含c1字符串, 包含返回索引, 不包含返回-1\r\nindex = 是否包含字符串(\"abc123\", \"c1\")", Usage="<p>判断A字符串中是否有B字符串, 并获取返回的索引</p>\r\n<p>用法:</p>\r\n<p>index = 是否包含字符串(\"A字符串\", \"B字符串\")</p>"},
new Cmd{Cat="字符串剪切板", Name="替换字符串", Code="#将字符串中的|替换为-\r\ns = 替换字符串(\"abc|123|321\", \"|\", \"-\")", Usage="<p>替换指定字符串为另一个字符串, 返回替换后的字符串</p>\r\n<p>用法:</p>\r\n<p>s = 是否包含字符串(\"字符串\", \"要替换字符串\", \"替换后的字符串\")</p>"},
new Cmd{Cat="字符串剪切板", Name="获取剪切板文本", Code="#从剪切板中获取文本\r\na = 获取剪切板文本()", Usage="<p>从剪切板中获取文本</p>\r\n<p>返回获取到的文本</p>\r\n<p>a = 获取剪切板文本()</p>\r\n"},
new Cmd{Cat="字符串剪切板", Name="设置剪切板文本", Code="#设置文本到剪切板中\r\n设置剪切板文本(\"要设置的内容\")", Usage="<p>设置文本到剪切板中</p>\r\n<p>成功返回1，失败返回0</p>\r\n<p>设置剪切板文本(\"要设置的内容\")</p>\r\n"},
new Cmd{Cat="其它", Name="加载DLL", Code="#加载程序目录中的DLL，返回句柄，失败返回0\r\n句柄 = 加载DLL(\"msdk.dll\")\r\n#也可以加载系统DLL\r\n句柄 = 加载DLL(\"user32.dll\")", Usage="<p>加载指定DLL（自动在程序目录查找），返回句柄，失败返回0</p>\r\n<p>        句柄 = 加载DLL(\"文件名或完整路径\")</p>\r\n<br/>\r\n<p>64位系统 + 64位 DLL 时在本进程内直接加载；</p>\r\n<p>x86 DLL 会自动通过 DllBridge32.exe 桥接调用，无需关心位数。</p>\r\n<p>可在初级视图\"DLL\"页查看每个 DLL 的架构与导出数量。</p>"},
new Cmd{Cat="其它", Name="调用DLL", Code="#调用DLL导出函数（stdcall，Windows API 常用）\r\n句柄 = 加载DLL(\"user32.dll\")\r\n返回值 = 调用DLL(句柄, \"GetSystemMetrics\", 0)\r\n消息框(\"提示\", \"屏幕宽度: \", 返回值)\r\n\r\n#也可以直接传DLL文件名，自动加载\r\n返回值 = 调用DLL(\"user32.dll\", \"GetSystemMetrics\", 0)", Usage="<p>调用 DLL 的导出函数，返回整数（0表示失败）</p>\r\n<p>        返回值 = 调用DLL(句柄或\"文件名\", \"函数名\", 参数1, 参数2, ...)</p>\r\n<br/>\r\n<p>参数最多8个：整数直接写，字符串写在引号里（按ANSI传递）</p>\r\n<p>本命令使用 stdcall 调用约定（Windows API 常用）；</p>\r\n<p>C语言导出函数（cdecl）请使用 调用DLL函数。</p>\r\n<p>要用返回的字符串可先用 获取DLL导出 查看函数列表。</p>"},
new Cmd{Cat="其它", Name="调用DLL函数", Code="#调用C语言导出函数（cdecl 调用约定）\r\n返回值 = 调用DLL函数(\"示例.dll\", \"add\", 1, 2)", Usage="<p>与 调用DLL 相同，但使用 cdecl 调用约定</p>\r\n<p>        返回值 = 调用DLL函数(句柄或\"文件名\", \"函数名\", 参数...)</p>\r\n<br/>\r\n<p>一般规则：Windows API 用 调用DLL(stdcall)；</p>\r\n<p>C/C++ 编译的普通导出函数用 调用DLL函数(cdecl)。</p>\r\n<p>如果一种约定调用后程序崩溃，换另一种试试。</p>"},
new Cmd{Cat="其它", Name="卸载DLL", Code="#卸载已加载的DLL\r\n句柄 = 加载DLL(\"msdk.dll\")\r\n卸载DLL(句柄)", Usage="<p>卸载已加载的DLL，成功返回1</p>\r\n<p>        卸载DLL(句柄)</p>"},
new Cmd{Cat="其它", Name="获取DLL导出", Code="#获取DLL的全部导出函数名，保存到数组变量中\r\nn = 获取DLL导出(\"msdk.dll\", 导出)\r\ni = 0\r\n循环(i < n)\r\n开始\r\n	输出调试(导出[i])\r\n	i = i + 1\r\n结束", Usage="<p>读取 DLL 的导出函数名列表（不加载DLL）</p>\r\n<p>        n = 获取DLL导出(\"文件名\", 数组变量)</p>\r\n<br/>\r\n<p>成功 n 为导出函数数量，名字存入数组变量：导出[0]、导出[1]...</p>\r\n<p>失败 n 为 0。</p>"},
};
}}
